package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_tanh_TriageGen4Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testTanh_NaN() {
        Complex c = Complex.NaN;
        Complex result = c.tanh();
        Assert.assertTrue("Result should be NaN", result.isNaN());
    }

    @Test
    public void testTanh_Zero() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.tanh();
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_RealOnly() {
        // tanh(x) for real x
        double x = 1.0;
        Complex c = new Complex(x, 0.0);
        Complex result = c.tanh();

        double expectedReal = Math.tanh(x);
        double expectedImag = 0.0;

        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_ImaginaryOnly() {
        // tanh(iy) = i * tan(y)
        double y = 0.5;
        Complex c = new Complex(0.0, y);
        Complex result = c.tanh();

        double expectedReal = 0.0;
        double expectedImag = Math.tan(y);

        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_Complex() {
        // Test with a standard complex number
        double re = 0.5;
        double im = 0.5;
        Complex c = new Complex(re, im);
        Complex result = c.tanh();

        // Manual calculation check using standard identity: 
        // tanh(a + bi) = (sinh(2a) + i sin(2b)) / (cosh(2a) + cos(2b))
        double real2 = 2.0 * re;
        double imag2 = 2.0 * im;
        double denom = Math.cosh(real2) + Math.cos(imag2);
        double expectedReal = Math.sinh(real2) / denom;
        double expectedImag = Math.sin(imag2) / denom;

        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_LargeReal() {
        // As real part goes to infinity, tanh(z) approaches 1
        Complex c = new Complex(100.0, 0.0);
        Complex result = c.tanh();
        Assert.assertEquals(1.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTanh_NegativeValues() {
        // tanh(-z) = -tanh(z)
        Complex c = new Complex(-0.5, -0.5);
        Complex result = c.tanh();

        Complex posC = new Complex(0.5, 0.5);
        Complex posResult = posC.tanh();

        Assert.assertEquals(-posResult.getReal(), result.getReal(), EPSILON);
        Assert.assertEquals(-posResult.getImaginary(), result.getImaginary(), EPSILON);
    }
}
